import { useState, useEffect, useMemo } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Progress } from "@/components/ui/progress";
import {
  Building2, Plus, Search, Users, AlertTriangle,
  Trash2, Edit, User,
  ChevronRight, RefreshCw, CheckCircle2, Loader2,
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";

// ── Types ─────────────────────────────────────────────────────────────────────
type ClientStatus = "active" | "onboarding" | "at-risk" | "churned";
type ContractTier = "enterprise" | "professional" | "starter";

interface ClientContact {
  name: string;
  role: string;
  email: string;
}

interface Client {
  id: string;
  name: string;
  industry: string;
  status: ClientStatus;
  tier: ContractTier;
  contract_value: number;
  renewal_date: string;
  risk_score: number;
  active_incidents: number;
  open_vulns: number;
  critical_alerts: number;
  analyst_assigned: string;
  last_report_date: string;
  sla_compliance: number;
  onboarded_date: string;
  contacts: ClientContact[];
  notes: string;
}

// ── Constants ─────────────────────────────────────────────────────────────────
const INDUSTRIES = [
  "Healthcare", "Finance", "Retail", "Government", "Technology",
  "Manufacturing", "Education", "Aerospace", "Crypto/Web3", "Legal",
  "Energy", "Pharmaceutical",
];

const ANALYSTS = [
  "Sarah Chen", "Marcus Webb", "Priya Nair", "James Okafor",
  "Elena Vasquez", "Tom Briggs",
];

const STATUS_COLORS: Record<ClientStatus, string> = {
  active: "bg-green-500/15 text-green-400 border-green-500/40",
  onboarding: "bg-blue-400/15 text-blue-400 border-blue-400/40",
  "at-risk": "bg-orange-400/15 text-orange-400 border-orange-400/40",
  churned: "bg-red-500/15 text-red-400 border-red-500/40",
};

const TIER_COLORS: Record<ContractTier, string> = {
  enterprise: "bg-primary/10 text-primary border-primary/30",
  professional: "bg-blue-400/15 text-blue-400 border-blue-400/40",
  starter: "text-muted-foreground border-border/60",
};

// ── Helpers ───────────────────────────────────────────────────────────────────
function formatCurrency(value: number): string {
  if (value >= 1_000_000) return `$${(value / 1_000_000).toFixed(1)}M`;
  if (value >= 1_000) return `$${(value / 1_000).toFixed(0)}K`;
  return `$${value}`;
}

function formatTotalValue(value: number): string {
  return `$${(value / 1_000_000).toFixed(2)}M`;
}

function slaColor(pct: number): string {
  if (pct >= 90) return "text-green-400";
  if (pct >= 70) return "text-orange-400";
  return "text-red-400";
}

function riskColor(score: number): string {
  if (score <= 40) return "text-green-400";
  if (score <= 70) return "text-orange-400";
  return "text-red-400";
}

function riskBarColor(score: number): string {
  if (score <= 40) return "bg-green-500";
  if (score <= 70) return "bg-orange-400";
  return "bg-red-500";
}

function daysUntil(dateStr: string): number {
  return Math.ceil((new Date(dateStr).getTime() - Date.now()) / 86400000);
}

// Row from Supabase — snake_case, contacts is Json
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function rowToClient(row: any): Client {
  return {
    id: row.id,
    name: row.name,
    industry: row.industry ?? "",
    status: (row.status ?? "active") as ClientStatus,
    tier: (row.tier ?? "starter") as ContractTier,
    contract_value: Number(row.contract_value ?? 0),
    renewal_date: row.renewal_date ?? "",
    risk_score: Number(row.risk_score ?? 0),
    active_incidents: Number(row.active_incidents ?? 0),
    open_vulns: Number(row.open_vulns ?? 0),
    critical_alerts: Number(row.critical_alerts ?? 0),
    analyst_assigned: row.analyst_assigned ?? "",
    last_report_date: row.last_report_date ?? "",
    sla_compliance: Number(row.sla_compliance ?? 100),
    onboarded_date: row.onboarded_date ?? "",
    contacts: Array.isArray(row.contacts) ? (row.contacts as ClientContact[]) : [],
    notes: row.notes ?? "",
  };
}

const BLANK_FORM: Omit<Client, "id"> = {
  name: "", industry: "Technology", status: "onboarding", tier: "starter",
  contract_value: 0, renewal_date: "", risk_score: 0, active_incidents: 0,
  open_vulns: 0, critical_alerts: 0, analyst_assigned: ANALYSTS[0],
  last_report_date: "", sla_compliance: 100, onboarded_date: new Date().toISOString().slice(0, 10),
  contacts: [], notes: "",
};

// ── Main Component ────────────────────────────────────────────────────────────
export default function ClientManagement() {
  const { toast } = useToast();
  const [clients, setClients] = useState<Client[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [filterIndustry, setFilterIndustry] = useState("all");
  const [filterTier, setFilterTier] = useState("all");
  const [filterAnalyst, setFilterAnalyst] = useState("all");
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);
  const [addOpen, setAddOpen] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [form, setForm] = useState<Omit<Client, "id">>(BLANK_FORM);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editNotes, setEditNotes] = useState("");
  const [saving, setSaving] = useState(false);

  // ── Fetch ──
  const fetchClients = async () => {
    setLoading(true);
    setError(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data, error: err } = await (supabase as any)
      .from("clients")
      .select("*")
      .order("name");
    if (err) {
      setError(err.message);
      toast({ title: "Failed to load clients", description: err.message, variant: "destructive" });
    } else {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      setClients((data as any[]).map(rowToClient));
    }
    setLoading(false);
  };

  useEffect(() => { fetchClients(); }, []);

  // ── Stats ──
  const stats = useMemo(() => {
    const active = clients.filter(c => c.status === "active").length;
    const atRisk = clients.filter(c => c.status === "at-risk").length;
    const totalValue = clients.reduce((s, c) => s + c.contract_value, 0);
    return { total: clients.length, active, atRisk, totalValue };
  }, [clients]);

  // ── Filtered clients ──
  const filtered = useMemo(() => {
    return clients.filter(c => {
      const q = search.toLowerCase();
      const matchSearch = !q || c.name.toLowerCase().includes(q) || c.industry.toLowerCase().includes(q) || c.analyst_assigned.toLowerCase().includes(q);
      const matchIndustry = filterIndustry === "all" || c.industry === filterIndustry;
      const matchTier = filterTier === "all" || c.tier === filterTier;
      const matchAnalyst = filterAnalyst === "all" || c.analyst_assigned === filterAnalyst;
      return matchSearch && matchIndustry && matchTier && matchAnalyst;
    });
  }, [clients, search, filterIndustry, filterTier, filterAnalyst]);

  const atRiskClients = useMemo(() => filtered.filter(c => c.status === "at-risk"), [filtered]);
  const renewalDue = useMemo(() => filtered.filter(c => c.renewal_date && daysUntil(c.renewal_date) <= 90).sort((a, b) => daysUntil(a.renewal_date) - daysUntil(b.renewal_date)), [filtered]);
  const onboarding = useMemo(() => filtered.filter(c => c.status === "onboarding"), [filtered]);

  // ── Save / Delete ──
  const handleSave = async () => {
    if (!form.name.trim()) { toast({ title: "Name required", variant: "destructive" }); return; }
    setSaving(true);
    const payload = {
      name: form.name,
      industry: form.industry,
      status: form.status,
      tier: form.tier,
      contract_value: form.contract_value,
      renewal_date: form.renewal_date || null,
      risk_score: form.risk_score,
      active_incidents: form.active_incidents,
      open_vulns: form.open_vulns,
      critical_alerts: form.critical_alerts,
      analyst_assigned: form.analyst_assigned,
      last_report_date: form.last_report_date || null,
      sla_compliance: form.sla_compliance,
      onboarded_date: form.onboarded_date || null,
      contacts: form.contacts,
      notes: form.notes,
    };

    if (editingId) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error: err } = await (supabase as any)
        .from("clients")
        .update(payload)
        .eq("id", editingId);
      if (err) {
        toast({ title: "Update failed", description: err.message, variant: "destructive" });
      } else {
        toast({ title: "Client updated", description: form.name });
        await fetchClients();
      }
    } else {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error: err } = await (supabase as any)
        .from("clients")
        .insert([payload])
        .select();
      if (err) {
        toast({ title: "Insert failed", description: err.message, variant: "destructive" });
      } else {
        toast({ title: "Client added", description: form.name });
        await fetchClients();
      }
    }
    setSaving(false);
    setAddOpen(false);
    setEditingId(null);
    setForm(BLANK_FORM);
  };

  const handleDelete = async (id: string) => {
    const client = clients.find(c => c.id === id);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { error: err } = await (supabase as any)
      .from("clients")
      .delete()
      .eq("id", id);
    if (err) {
      toast({ title: "Delete failed", description: err.message, variant: "destructive" });
    } else {
      setClients(prev => prev.filter(c => c.id !== id));
      setDetailOpen(false);
      toast({ title: "Client removed", description: client?.name, variant: "destructive" });
    }
  };

  const openEdit = (client: Client) => {
    const { id, ...rest } = client;
    void id;
    setForm(rest);
    setEditingId(client.id);
    setAddOpen(true);
  };

  const saveNotes = async () => {
    if (!selectedClient) return;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { error: err } = await (supabase as any)
      .from("clients")
      .update({ notes: editNotes })
      .eq("id", selectedClient.id);
    if (err) {
      toast({ title: "Failed to save notes", description: err.message, variant: "destructive" });
    } else {
      setClients(prev => prev.map(c => c.id === selectedClient.id ? { ...c, notes: editNotes } : c));
      setSelectedClient({ ...selectedClient, notes: editNotes });
      toast({ title: "Notes saved" });
      setEditMode(false);
    }
  };

  const openDetail = (client: Client) => {
    setSelectedClient(client);
    setEditNotes(client.notes);
    setEditMode(false);
    setDetailOpen(true);
  };

  // ── Loading / Error ──
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64 gap-3 text-muted-foreground">
        <Loader2 className="w-5 h-5 animate-spin" />
        <span className="text-sm">Loading clients…</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center h-64 gap-3 text-muted-foreground">
        <AlertTriangle className="w-8 h-8 text-destructive" />
        <p className="text-sm font-medium text-destructive">Failed to load clients</p>
        <p className="text-xs text-muted-foreground">{error}</p>
        <Button variant="outline" size="sm" onClick={fetchClients}>
          <RefreshCw className="w-3.5 h-3.5 mr-1" /> Retry
        </Button>
      </div>
    );
  }

  // ── Client Table Row ──
  const ClientRow = ({ client }: { client: Client }) => (
    <div
      className="flex flex-wrap items-center gap-2 px-4 py-3 border-b border-border/40 hover:bg-muted/30 cursor-pointer transition-colors"
      onClick={() => openDetail(client)}
    >
      <div className="flex-1 min-w-[160px]">
        <div className="font-medium text-sm truncate">{client.name}</div>
        <div className="text-xs text-muted-foreground font-mono">{client.id.slice(0, 8)}…</div>
      </div>
      <div className="hidden sm:block w-28">
        <Badge variant="outline" className="text-xs">{client.industry}</Badge>
      </div>
      <div className="w-24">
        <Badge variant="outline" className={`text-xs ${STATUS_COLORS[client.status]}`}>
          {client.status}
        </Badge>
      </div>
      <div className="w-20 hidden md:block">
        <Badge variant="outline" className={`text-xs capitalize ${TIER_COLORS[client.tier]}`}>
          {client.tier}
        </Badge>
      </div>
      <div className="w-28 hidden lg:block">
        <div className="flex items-center gap-1.5">
          <div className="flex-1 h-1.5 bg-muted rounded-full overflow-hidden">
            <div className={`h-full rounded-full ${riskBarColor(client.risk_score)}`} style={{ width: `${client.risk_score}%` }} />
          </div>
          <span className={`text-xs font-mono ${riskColor(client.risk_score)}`}>{client.risk_score}</span>
        </div>
      </div>
      <div className="w-16 text-center hidden md:block">
        <span className={`text-sm font-bold ${slaColor(client.sla_compliance)}`}>{client.sla_compliance}%</span>
      </div>
      <div className="w-16 text-center hidden lg:block">
        {client.active_incidents > 0
          ? <span className="text-red-400 text-sm font-bold">{client.active_incidents}</span>
          : <span className="text-muted-foreground text-sm">0</span>}
      </div>
      <div className="w-28 hidden xl:block text-xs text-muted-foreground truncate">{client.analyst_assigned}</div>
      <div className="w-28 hidden xl:block text-xs text-muted-foreground">{client.renewal_date}</div>
      <div className="w-20 text-right text-xs font-mono text-primary">{formatCurrency(client.contract_value)}</div>
      <ChevronRight className="w-4 h-4 text-muted-foreground" />
    </div>
  );

  const ClientTableHeader = () => (
    <div className="flex flex-wrap items-center gap-2 px-4 py-2 border-b border-border/60 text-xs text-muted-foreground font-medium bg-muted/20">
      <div className="flex-1 min-w-[160px]">Client</div>
      <div className="hidden sm:block w-28">Industry</div>
      <div className="w-24">Status</div>
      <div className="w-20 hidden md:block">Tier</div>
      <div className="w-28 hidden lg:block">Risk Score</div>
      <div className="w-16 text-center hidden md:block">SLA</div>
      <div className="w-16 text-center hidden lg:block">Incidents</div>
      <div className="w-28 hidden xl:block">Analyst</div>
      <div className="w-28 hidden xl:block">Renewal</div>
      <div className="w-20 text-right">Value</div>
      <div className="w-4" />
    </div>
  );

  const ClientTable = ({ list }: { list: Client[] }) => (
    <div className="rounded-md border border-border/60 overflow-hidden">
      <ClientTableHeader />
      {list.length === 0
        ? <div className="text-center py-12 text-muted-foreground">
            <Users className="w-10 h-10 mx-auto mb-3 opacity-30" />
            <p className="text-sm">No clients match your filters.</p>
            <Button variant="outline" size="sm" className="mt-3" onClick={() => setAddOpen(true)}>
              <Plus className="w-3.5 h-3.5 mr-1" /> Add Client
            </Button>
          </div>
        : list.map(c => <ClientRow key={c.id} client={c} />)}
    </div>
  );

  return (
    <div className="p-4 md:p-6 space-y-5 max-w-screen-2xl mx-auto">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-xl font-bold flex items-center gap-2">
            <Building2 className="w-5 h-5 text-primary" /> Client Management
          </h1>
          <p className="text-xs text-muted-foreground mt-0.5">MSSP portfolio — account health, SLA compliance, and risk posture</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={async () => { await fetchClients(); toast({ title: "Refreshed" }); }}>
            <RefreshCw className="w-3.5 h-3.5 mr-1" /> Refresh
          </Button>
          <Button size="sm" onClick={() => { setForm(BLANK_FORM); setEditingId(null); setAddOpen(true); }}>
            <Plus className="w-3.5 h-3.5 mr-1" /> Add Client
          </Button>
        </div>
      </div>

      {/* Stat Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Card className="border-border/60 bg-card/60">
          <CardContent className="px-4 py-3 text-center">
            <div className="text-2xl font-bold tabular-nums">{stats.total}</div>
            <div className="text-xs text-muted-foreground mt-0.5">Total Clients</div>
          </CardContent>
        </Card>
        <Card className="border-border/60 bg-card/60">
          <CardContent className="px-4 py-3 text-center">
            <div className="text-2xl font-bold tabular-nums text-green-400">{stats.active}</div>
            <div className="text-xs text-muted-foreground mt-0.5">Active</div>
          </CardContent>
        </Card>
        <Card className="border-border/60 bg-card/60">
          <CardContent className="px-4 py-3 text-center">
            <div className="text-2xl font-bold tabular-nums text-orange-400">{stats.atRisk}</div>
            <div className="text-xs text-muted-foreground mt-0.5">At Risk</div>
          </CardContent>
        </Card>
        <Card className="border-border/60 bg-card/60">
          <CardContent className="px-4 py-3 text-center">
            <div className="text-2xl font-bold tabular-nums text-primary">{formatTotalValue(stats.totalValue)}</div>
            <div className="text-xs text-muted-foreground mt-0.5">Total Contract Value</div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-2">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-2.5 top-2 w-3.5 h-3.5 text-muted-foreground" />
          <Input placeholder="Search clients…" className="pl-8 h-8 text-sm" value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <Select value={filterIndustry} onValueChange={setFilterIndustry}>
          <SelectTrigger className="h-8 w-36 text-xs"><SelectValue placeholder="Industry" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Industries</SelectItem>
            {INDUSTRIES.map(i => <SelectItem key={i} value={i}>{i}</SelectItem>)}
          </SelectContent>
        </Select>
        <Select value={filterTier} onValueChange={setFilterTier}>
          <SelectTrigger className="h-8 w-32 text-xs"><SelectValue placeholder="Tier" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Tiers</SelectItem>
            <SelectItem value="enterprise">Enterprise</SelectItem>
            <SelectItem value="professional">Professional</SelectItem>
            <SelectItem value="starter">Starter</SelectItem>
          </SelectContent>
        </Select>
        <Select value={filterAnalyst} onValueChange={setFilterAnalyst}>
          <SelectTrigger className="h-8 w-36 text-xs"><SelectValue placeholder="Analyst" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Analysts</SelectItem>
            {ANALYSTS.map(a => <SelectItem key={a} value={a}>{a}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      {/* Tabs */}
      <Tabs defaultValue="all">
        <TabsList className="h-8">
          <TabsTrigger value="all" className="text-xs">All Clients ({filtered.length})</TabsTrigger>
          <TabsTrigger value="atrisk" className="text-xs">At Risk ({atRiskClients.length})</TabsTrigger>
          <TabsTrigger value="renewals" className="text-xs">Renewals Due ({renewalDue.length})</TabsTrigger>
          <TabsTrigger value="onboarding" className="text-xs">Onboarding ({onboarding.length})</TabsTrigger>
        </TabsList>
        <TabsContent value="all" className="mt-3"><ClientTable list={filtered} /></TabsContent>
        <TabsContent value="atrisk" className="mt-3">
          {atRiskClients.length === 0
            ? <div className="text-center py-12 text-muted-foreground text-sm"><CheckCircle2 className="w-8 h-8 mx-auto mb-2 text-green-400 opacity-60" />No at-risk clients</div>
            : <ClientTable list={atRiskClients} />}
        </TabsContent>
        <TabsContent value="renewals" className="mt-3">
          {renewalDue.length === 0
            ? <div className="text-center py-12 text-muted-foreground text-sm">No renewals due in the next 90 days</div>
            : renewalDue.map(c => (
              <div key={c.id} className="flex items-center justify-between p-3 border-b border-border/40 hover:bg-muted/30 cursor-pointer" onClick={() => openDetail(c)}>
                <div>
                  <span className="font-medium text-sm">{c.name}</span>
                  <Badge variant="outline" className={`ml-2 text-xs ${STATUS_COLORS[c.status]}`}>{c.status}</Badge>
                </div>
                <div className="flex items-center gap-4">
                  <span className={`text-xs font-mono ${daysUntil(c.renewal_date) <= 30 ? "text-red-400" : "text-orange-400"}`}>
                    {daysUntil(c.renewal_date)}d left
                  </span>
                  <span className="text-xs text-muted-foreground">{c.renewal_date}</span>
                  <span className="text-xs font-mono text-primary">{formatCurrency(c.contract_value)}</span>
                </div>
              </div>
            ))}
        </TabsContent>
        <TabsContent value="onboarding" className="mt-3"><ClientTable list={onboarding} /></TabsContent>
      </Tabs>

      {/* Client Detail Dialog */}
      <Dialog open={detailOpen} onOpenChange={setDetailOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          {selectedClient && (
            <>
              <DialogHeader>
                <div className="flex items-center gap-2 flex-wrap">
                  <Building2 className="w-4 h-4 text-primary" />
                  <span className="font-semibold">{selectedClient.name}</span>
                  <Badge variant="outline" className={`text-xs ml-1 ${STATUS_COLORS[selectedClient.status]}`}>{selectedClient.status}</Badge>
                  <Badge variant="outline" className={`text-xs capitalize ${TIER_COLORS[selectedClient.tier]}`}>{selectedClient.tier}</Badge>
                </div>
              </DialogHeader>
              <div className="space-y-4 pt-1">
                {/* Key Metrics */}
                <div className="grid grid-cols-3 gap-2">
                  {[
                    { label: "Contract Value", value: formatCurrency(selectedClient.contract_value), color: "text-primary" },
                    { label: "SLA Compliance", value: `${selectedClient.sla_compliance}%`, color: slaColor(selectedClient.sla_compliance) },
                    { label: "Risk Score", value: `${selectedClient.risk_score}/100`, color: riskColor(selectedClient.risk_score) },
                    { label: "Active Incidents", value: String(selectedClient.active_incidents), color: selectedClient.active_incidents > 0 ? "text-red-400" : "text-green-400" },
                    { label: "Open Vulns", value: String(selectedClient.open_vulns), color: selectedClient.open_vulns > 20 ? "text-orange-400" : "text-muted-foreground" },
                    { label: "Critical Alerts", value: String(selectedClient.critical_alerts), color: selectedClient.critical_alerts > 0 ? "text-red-400" : "text-green-400" },
                  ].map(m => (
                    <Card key={m.label} className="border-border/60 bg-card/60">
                      <CardContent className="px-3 py-2 text-center">
                        <div className={`text-lg font-bold tabular-nums ${m.color}`}>{m.value}</div>
                        <div className="text-xs text-muted-foreground mt-0.5">{m.label}</div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
                {/* Risk Bar */}
                <div>
                  <div className="flex justify-between text-xs mb-1">
                    <span className="text-muted-foreground">Risk Score</span>
                    <span className={riskColor(selectedClient.risk_score)}>{selectedClient.risk_score <= 40 ? "Low" : selectedClient.risk_score <= 70 ? "Medium" : "High"}</span>
                  </div>
                  <Progress value={selectedClient.risk_score} className="h-2" />
                </div>
                {/* SLA Bar */}
                <div>
                  <div className="flex justify-between text-xs mb-1">
                    <span className="text-muted-foreground">SLA Compliance</span>
                    <span className={slaColor(selectedClient.sla_compliance)}>{selectedClient.sla_compliance}%</span>
                  </div>
                  <Progress value={selectedClient.sla_compliance} className="h-2" />
                </div>
                {/* Details */}
                <div className="grid grid-cols-2 gap-x-6 gap-y-1.5 text-xs">
                  <div><span className="text-muted-foreground">Industry:</span> <span>{selectedClient.industry}</span></div>
                  <div><span className="text-muted-foreground">Analyst:</span> <span>{selectedClient.analyst_assigned}</span></div>
                  <div><span className="text-muted-foreground">Onboarded:</span> <span>{selectedClient.onboarded_date}</span></div>
                  <div><span className="text-muted-foreground">Renewal:</span> <span className={selectedClient.renewal_date && daysUntil(selectedClient.renewal_date) <= 60 ? "text-orange-400 font-medium" : ""}>{selectedClient.renewal_date}{selectedClient.renewal_date ? ` (${daysUntil(selectedClient.renewal_date)}d)` : ""}</span></div>
                  <div><span className="text-muted-foreground">Last Report:</span> <span>{selectedClient.last_report_date}</span></div>
                  <div><span className="text-muted-foreground">ID:</span> <span className="font-mono text-[10px]">{selectedClient.id}</span></div>
                </div>
                {/* Contacts */}
                {selectedClient.contacts.length > 0 && (
                  <div>
                    <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">Contacts</h4>
                    <div className="space-y-1.5">
                      {selectedClient.contacts.map((ct, i) => (
                        <div key={i} className="flex items-center gap-3 text-xs p-2 rounded-md bg-muted/30">
                          <User className="w-3.5 h-3.5 text-muted-foreground" />
                          <span className="font-medium">{ct.name}</span>
                          <Badge variant="outline" className="text-xs py-0">{ct.role}</Badge>
                          <span className="text-muted-foreground ml-auto">{ct.email}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                {/* Notes */}
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">Notes</h4>
                    <Button variant="ghost" size="sm" className="h-6 text-xs" onClick={() => setEditMode(!editMode)}>
                      <Edit className="w-3 h-3 mr-1" />{editMode ? "Cancel" : "Edit"}
                    </Button>
                  </div>
                  {editMode
                    ? <div className="space-y-2">
                        <textarea
                          className="w-full text-xs p-2 rounded-md border border-border/60 bg-background/50 resize-none focus:outline-none focus:ring-1 focus:ring-primary"
                          rows={4}
                          value={editNotes}
                          onChange={e => setEditNotes(e.target.value)}
                        />
                        <Button size="sm" onClick={saveNotes} className="h-7 text-xs">Save Notes</Button>
                      </div>
                    : <p className="text-xs text-muted-foreground bg-muted/20 rounded-md p-2 leading-relaxed">{selectedClient.notes || "No notes."}</p>}
                </div>
              </div>
              <DialogFooter className="flex gap-2 pt-2">
                <Button variant="outline" size="sm" onClick={() => { setDetailOpen(false); openEdit(selectedClient); }}>
                  <Edit className="w-3.5 h-3.5 mr-1" /> Edit
                </Button>
                <Button variant="destructive" size="sm" onClick={() => handleDelete(selectedClient.id)}>
                  <Trash2 className="w-3.5 h-3.5 mr-1" /> Delete
                </Button>
                <Button variant="ghost" size="sm" onClick={() => setDetailOpen(false)}>Close</Button>
              </DialogFooter>
            </>
          )}
        </DialogContent>
      </Dialog>

      {/* Add / Edit Dialog */}
      <Dialog open={addOpen} onOpenChange={v => { setAddOpen(v); if (!v) { setEditingId(null); setForm(BLANK_FORM); } }}>
        <DialogContent className="max-w-xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <div className="font-semibold">{editingId ? "Edit Client" : "Add Client"}</div>
          </DialogHeader>
          <div className="grid grid-cols-2 gap-3 text-sm pt-1">
            {/* Name */}
            <div className="col-span-2">
              <label className="text-xs text-muted-foreground mb-1 block">Company Name *</label>
              <Input value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} placeholder="Acme Corp" className="h-8 text-sm" />
            </div>
            {/* Industry */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Industry</label>
              <Select value={form.industry} onValueChange={v => setForm(f => ({ ...f, industry: v }))}>
                <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                <SelectContent>{INDUSTRIES.map(i => <SelectItem key={i} value={i}>{i}</SelectItem>)}</SelectContent>
              </Select>
            </div>
            {/* Status */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Status</label>
              <Select value={form.status} onValueChange={v => setForm(f => ({ ...f, status: v as ClientStatus }))}>
                <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {(["active","onboarding","at-risk","churned"] as ClientStatus[]).map(s => <SelectItem key={s} value={s}>{s}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            {/* Tier */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Tier</label>
              <Select value={form.tier} onValueChange={v => setForm(f => ({ ...f, tier: v as ContractTier }))}>
                <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {(["enterprise","professional","starter"] as ContractTier[]).map(t => <SelectItem key={t} value={t}>{t}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            {/* Analyst */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Analyst Assigned</label>
              <Select value={form.analyst_assigned} onValueChange={v => setForm(f => ({ ...f, analyst_assigned: v }))}>
                <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
                <SelectContent>{ANALYSTS.map(a => <SelectItem key={a} value={a}>{a}</SelectItem>)}</SelectContent>
              </Select>
            </div>
            {/* Contract Value */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Contract Value ($)</label>
              <Input type="number" value={form.contract_value} onChange={e => setForm(f => ({ ...f, contract_value: Number(e.target.value) }))} className="h-8 text-sm" />
            </div>
            {/* Renewal Date */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Renewal Date</label>
              <Input type="date" value={form.renewal_date} onChange={e => setForm(f => ({ ...f, renewal_date: e.target.value }))} className="h-8 text-sm" />
            </div>
            {/* Risk Score */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Risk Score (0-100)</label>
              <Input type="number" min={0} max={100} value={form.risk_score} onChange={e => setForm(f => ({ ...f, risk_score: Number(e.target.value) }))} className="h-8 text-sm" />
            </div>
            {/* SLA */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">SLA Compliance (%)</label>
              <Input type="number" min={0} max={100} value={form.sla_compliance} onChange={e => setForm(f => ({ ...f, sla_compliance: Number(e.target.value) }))} className="h-8 text-sm" />
            </div>
            {/* Active Incidents */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Active Incidents</label>
              <Input type="number" min={0} value={form.active_incidents} onChange={e => setForm(f => ({ ...f, active_incidents: Number(e.target.value) }))} className="h-8 text-sm" />
            </div>
            {/* Open Vulns */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Open Vulnerabilities</label>
              <Input type="number" min={0} value={form.open_vulns} onChange={e => setForm(f => ({ ...f, open_vulns: Number(e.target.value) }))} className="h-8 text-sm" />
            </div>
            {/* Critical Alerts */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Critical Alerts</label>
              <Input type="number" min={0} value={form.critical_alerts} onChange={e => setForm(f => ({ ...f, critical_alerts: Number(e.target.value) }))} className="h-8 text-sm" />
            </div>
            {/* Onboarded Date */}
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Onboarded Date</label>
              <Input type="date" value={form.onboarded_date} onChange={e => setForm(f => ({ ...f, onboarded_date: e.target.value }))} className="h-8 text-sm" />
            </div>
            {/* Notes */}
            <div className="col-span-2">
              <label className="text-xs text-muted-foreground mb-1 block">Notes</label>
              <textarea
                className="w-full text-xs p-2 rounded-md border border-border/60 bg-background/50 resize-none focus:outline-none focus:ring-1 focus:ring-primary"
                rows={3}
                value={form.notes}
                onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
                placeholder="Account notes…"
              />
            </div>
          </div>
          <DialogFooter className="pt-2">
            <Button variant="ghost" size="sm" onClick={() => setAddOpen(false)} disabled={saving}>Cancel</Button>
            <Button size="sm" onClick={handleSave} disabled={saving}>
              {saving && <Loader2 className="w-3.5 h-3.5 mr-1 animate-spin" />}
              {editingId ? "Save Changes" : "Add Client"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
